import shutil
from pathlib import Path


def piano(cartella):
    cartella = Path(cartella)
    mosse = []
    for f in sorted(cartella.glob("*.csv")):
        pezzi = f.stem.split("_")
        if len(pezzi) != 3 or not pezzi[2].isdigit():
            continue
        tipo, materiale, n = pezzi
        mosse.append((f, cartella / materiale / f"{tipo}_{int(n):03d}.csv"))
    return mosse


def applica(mosse):
    for _, dst in mosse:
        if dst.exists():
            raise FileExistsError(dst)
    for src, dst in mosse:
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(src, dst)


def conteggio(cartella):
    return {d.name: len(list(d.glob("*.csv"))) for d in sorted(Path(cartella).iterdir()) if d.is_dir()}
